import { ChevronLeft, ChevronRight } from "lucide-solid";
import type { JSX } from "solid-js";
import { For, Show } from "solid-js";

import { cn } from "@/lib/utils";
import { Button } from "@/registry/kobalte/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/registry/kobalte/ui/select";
import { Skeleton } from "@/registry/kobalte/ui/skeleton";
import { useDataGrid } from "./data-grid";

interface DataGridPaginationProps {
  sizes?: number[];
  sizesInfo?: string;
  sizesLabel?: string;
  sizesDescription?: string;
  sizesSkeleton?: JSX.Element;
  more?: boolean;
  moreLimit?: number;
  info?: string;
  infoSkeleton?: JSX.Element;
  class?: string;
  rowsPerPageLabel?: string;
  previousPageLabel?: string;
  nextPageLabel?: string;
  ellipsisText?: string;
}

const DATA_GRID_PAGINATION_DEFAULT_SIZES = [5, 10, 25, 50, 100];

function DataGridPagination(props: DataGridPaginationProps): JSX.Element {
  const grid = useDataGrid();

  // Upstream spreads a `defaultProps` object over the incoming props. The two
  // JSX defaults are resolved lazily instead, so the skeleton nodes are only
  // built when the grid is actually loading.
  const sizes = () => props.sizes ?? DATA_GRID_PAGINATION_DEFAULT_SIZES;
  const sizesSkeleton = () => props.sizesSkeleton ?? <Skeleton class="h-8 w-44" />;
  const infoSkeleton = () => props.infoSkeleton ?? <Skeleton class="h-8 w-60" />;
  const moreLimitProp = () => props.moreLimit ?? 5;
  const info = () => props.info ?? "{from} - {to} of {count}";
  const rowsPerPageLabel = () => props.rowsPerPageLabel ?? "Rows per page";
  const previousPageLabel = () => props.previousPageLabel ?? "Go to previous page";
  const nextPageLabel = () => props.nextPageLabel ?? "Go to next page";
  const ellipsisText = () => props.ellipsisText ?? "...";

  const btnBaseClasses = "p-0 text-sm";
  const btnArrowClasses = `${btnBaseClasses} rtl:transform rtl:rotate-180`;

  // v9 has no `table.state`; every slice is read off the reactive store, which
  // is what makes these derivations update when the page changes.
  const pagination = () => grid.table.store.state.pagination;
  const pageIndex = () => pagination().pageIndex;
  const pageSize = () => pagination().pageSize;
  const from = () => (grid.recordCount === 0 ? 0 : pageIndex() * pageSize() + 1);
  const to = () => Math.min((pageIndex() + 1) * pageSize(), grid.recordCount);
  const pageCount = () => grid.table.getPageCount();

  // Replace placeholders in paginationInfo
  const paginationInfo = () =>
    info()
      .replaceAll("{from}", from().toString())
      .replaceAll("{to}", to().toString())
      .replaceAll("{count}", grid.recordCount.toString());

  // Pagination limit logic
  const paginationMoreLimit = () => moreLimitProp() || 5;

  // Determine the start and end of the pagination group
  const currentGroupStart = () =>
    Math.floor(pageIndex() / paginationMoreLimit()) * paginationMoreLimit();
  const currentGroupEnd = () => Math.min(currentGroupStart() + paginationMoreLimit(), pageCount());

  // Render page buttons based on the current group
  const pageButtonIndexes = () => {
    const buttons: number[] = [];
    for (let i = currentGroupStart(); i < currentGroupEnd(); i++) {
      buttons.push(i);
    }
    return buttons;
  };

  return (
    <div
      data-slot="data-grid-pagination"
      class={cn(
        "flex grow flex-col flex-wrap items-center justify-between gap-2.5 py-2.5 sm:flex-row sm:py-0",
        props.class,
      )}
    >
      <div class="order-2 flex flex-wrap items-center space-x-2.5 pb-2.5 sm:order-1 sm:pb-0">
        <Show when={!grid.isLoading} fallback={sizesSkeleton()}>
          <div class="text-muted-foreground text-sm">{rowsPerPageLabel()}</div>
          <Select
            options={sizes()}
            value={pageSize()}
            onChange={(value: number | null) => {
              if (value === null) return;
              grid.table.setPageSize(value);
            }}
            itemComponent={(itemProps) => (
              <SelectItem item={itemProps.item}>{itemProps.item.rawValue}</SelectItem>
            )}
            placement="bottom-start"
          >
            <SelectTrigger class="w-16" size="sm" aria-label={rowsPerPageLabel()}>
              <SelectValue<number>>{(state) => state.selectedOption()}</SelectValue>
            </SelectTrigger>
            {/*
              Kobalte anchors the listbox itself, so upstream's
              `alignItemWithTrigger={false}` has no counterpart; the anchor
              width variable is Kobalte's rather than Base UI's.
            */}
            <SelectContent class="min-w-(--kb-popper-anchor-width)" />
          </Select>
        </Show>
      </div>
      <div class="order-1 flex flex-col items-center justify-center gap-2.5 pt-2.5 sm:order-2 sm:flex-row sm:justify-end sm:pt-0">
        <Show when={!grid.isLoading} fallback={infoSkeleton()}>
          <div class="text-muted-foreground order-2 text-sm text-nowrap sm:order-1">
            {paginationInfo()}
          </div>
          <Show when={pageCount() > 1}>
            <div class="order-1 flex items-center space-x-1">
              <Button
                size="icon-sm"
                variant="ghost"
                class={btnArrowClasses}
                onClick={() => grid.table.previousPage()}
                disabled={!grid.table.getCanPreviousPage()}
              >
                <span class="sr-only">{previousPageLabel()}</span>
                <ChevronLeft class="size-4" />
              </Button>

              <Show when={currentGroupStart() > 0}>
                <Button
                  size="icon-sm"
                  class={btnBaseClasses}
                  variant="ghost"
                  onClick={() => grid.table.setPageIndex(currentGroupStart() - 1)}
                >
                  {ellipsisText()}
                </Button>
              </Show>

              <For each={pageButtonIndexes()}>
                {(index) => (
                  <Button
                    size="icon-sm"
                    variant="ghost"
                    class={cn(btnBaseClasses, "text-muted-foreground", {
                      "bg-accent text-accent-foreground": pageIndex() === index,
                    })}
                    onClick={() => {
                      if (pageIndex() !== index) {
                        grid.table.setPageIndex(index);
                      }
                    }}
                  >
                    {index + 1}
                  </Button>
                )}
              </For>

              <Show when={currentGroupEnd() < pageCount()}>
                <Button
                  class={btnBaseClasses}
                  variant="ghost"
                  size="icon-sm"
                  onClick={() => grid.table.setPageIndex(currentGroupEnd())}
                >
                  {ellipsisText()}
                </Button>
              </Show>

              <Button
                size="icon-sm"
                variant="ghost"
                class={btnArrowClasses}
                onClick={() => grid.table.nextPage()}
                disabled={!grid.table.getCanNextPage()}
              >
                <span class="sr-only">{nextPageLabel()}</span>
                <ChevronRight class="size-4" />
              </Button>
            </div>
          </Show>
        </Show>
      </div>
    </div>
  );
}

export type { DataGridPaginationProps };
export { DataGridPagination };

import type { Accessor, ComponentProps, JSX } from "solid-js";
import { createEffect, createSignal, onCleanup, Show, splitProps } from "solid-js";

import { cn } from "@/lib/utils";
import { useDataGrid } from "./data-grid";

const MIN_THUMB_SIZE = 24;
const FALLBACK_SCROLLBAR_SIZE = 12;

const INITIAL_METRICS = {
  hasVerticalOverflow: false,
  headerHeight: 0,
  horizontalScrollbarSize: 0,
  thumbHeight: 0,
  thumbTop: 0,
  trackHeight: 0,
} as const;

const SCROLLBAR_CLASS =
  "flex touch-none p-px transition-colors select-none data-[orientation=horizontal]:h-2.5 data-[orientation=horizontal]:flex-col data-[orientation=horizontal]:border-t data-[orientation=horizontal]:border-t-transparent data-[orientation=vertical]:h-full data-[orientation=vertical]:w-2 data-[orientation=vertical]:border-s data-[orientation=vertical]:border-s-transparent";

const SCROLLBAR_THUMB_CLASS = "bg-border rounded-full relative flex-1";

/**
 * Positioning and overflow behavior Base UI's `ScrollArea` supplies from its
 * own stylesheet. The block owns the scroll surface here (see the note on
 * `DataGridScrollArea`), so the equivalents are declared explicitly.
 */
const VIEWPORT_SCROLL_CLASS =
  "overflow-auto overscroll-contain [-ms-overflow-style:none] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden";

const SCROLLBAR_POSITION_CLASS = {
  horizontal: "absolute bottom-0 inset-x-0",
  vertical: "absolute top-0 end-0",
} as const;

type DataGridScrollAreaOrientation = "horizontal" | "vertical" | "both";

type ScrollbarMetrics = {
  hasVerticalOverflow: boolean;
  headerHeight: number;
  horizontalScrollbarSize: number;
  thumbHeight: number;
  thumbTop: number;
  trackHeight: number;
};

type ObservedElements = {
  header: HTMLElement | null;
  horizontalScrollbar: HTMLElement | null;
  table: HTMLElement | null;
  tableViewport: HTMLElement | null;
};

type DataGridScrollAreaProps = Omit<ComponentProps<"div">, "children" | "orientation"> & {
  children: JSX.Element;
  orientation?: DataGridScrollAreaOrientation;
};

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

function areMetricsEqual(next: ScrollbarMetrics, prev: ScrollbarMetrics) {
  return (
    next.hasVerticalOverflow === prev.hasVerticalOverflow &&
    next.headerHeight === prev.headerHeight &&
    next.horizontalScrollbarSize === prev.horizontalScrollbarSize &&
    next.thumbHeight === prev.thumbHeight &&
    next.thumbTop === prev.thumbTop &&
    next.trackHeight === prev.trackHeight
  );
}

function applyMetrics(element: HTMLElement, metrics: ScrollbarMetrics) {
  element.style.setProperty("--data-grid-scrollbar-header-height", `${metrics.headerHeight}px`);
  element.style.setProperty("--data-grid-scrollbar-thumb-height", `${metrics.thumbHeight}px`);
  element.style.setProperty("--data-grid-scrollbar-thumb-top", `${metrics.thumbTop}px`);
  element.style.setProperty("--data-grid-scrollbar-track-height", `${metrics.trackHeight}px`);
}

/**
 * Native-overflow scrollbar for one axis.
 *
 * Base UI's `ScrollArea.Scrollbar` / `ScrollArea.Thumb` pair is reimplemented
 * here rather than mapped onto `@/registry/kobalte/ui/scroll-area`: that
 * wrapper renders its own fixed `<ScrollBar />`, exposes no viewport ref, and
 * offers no way to attach the `data-slot` / `data-orientation` hooks or the
 * pinned-column inset this grid measures against. The public class names,
 * data attributes and geometry are the upstream ones.
 */
function DataGridScrollAreaScrollbar(props: {
  orientation: "horizontal" | "vertical";
  viewport: Accessor<HTMLDivElement | undefined>;
  style?: JSX.CSSProperties;
}) {
  const [track, setTrack] = createSignal<HTMLDivElement>();
  const [thumbSize, setThumbSize] = createSignal(0);
  const [thumbOffset, setThumbOffset] = createSignal(0);
  const [visible, setVisible] = createSignal(false);
  const isVertical = () => props.orientation === "vertical";

  let drag: { pointerId: number; start: number; startScroll: number } | null = null;

  const measure = () => {
    const viewport = props.viewport();
    const trackElement = track();

    if (!viewport || !trackElement) return;

    const trackSize = isVertical() ? trackElement.clientHeight : trackElement.clientWidth;
    const clientSize = isVertical() ? viewport.clientHeight : viewport.clientWidth;
    const scrollSize = isVertical() ? viewport.scrollHeight : viewport.scrollWidth;
    const maxScroll = Math.max(0, scrollSize - clientSize);

    if (trackSize <= 0 || maxScroll <= 0.5) {
      setVisible(false);
      return;
    }

    const size = clamp((clientSize / scrollSize) * trackSize, MIN_THUMB_SIZE, trackSize);
    const scrollOffset = isVertical() ? viewport.scrollTop : viewport.scrollLeft;

    setVisible(true);
    setThumbSize(size);
    setThumbOffset((scrollOffset / maxScroll) * Math.max(0, trackSize - size));
  };

  createEffect(() => {
    const viewport = props.viewport();
    const trackElement = track();

    if (!viewport || !trackElement) return;

    measure();
    viewport.addEventListener("scroll", measure, { passive: true });
    onCleanup(() => viewport.removeEventListener("scroll", measure));

    if (typeof ResizeObserver !== "undefined") {
      const observer = new ResizeObserver(measure);
      observer.observe(viewport);
      observer.observe(trackElement);
      onCleanup(() => observer.disconnect());
    }
  });

  const scrollToThumbOffset = (nextOffset: number) => {
    const viewport = props.viewport();
    const trackElement = track();

    if (!viewport || !trackElement) return;

    const trackSize = isVertical() ? trackElement.clientHeight : trackElement.clientWidth;
    const clientSize = isVertical() ? viewport.clientHeight : viewport.clientWidth;
    const scrollSize = isVertical() ? viewport.scrollHeight : viewport.scrollWidth;
    const maxScroll = Math.max(0, scrollSize - clientSize);
    const maxOffset = Math.max(0, trackSize - thumbSize());

    if (maxScroll === 0 || maxOffset === 0) return;

    const ratio = clamp(nextOffset, 0, maxOffset) / maxOffset;

    if (isVertical()) {
      viewport.scrollTop = ratio * maxScroll;
    } else {
      viewport.scrollLeft = ratio * maxScroll;
    }
  };

  return (
    <div
      ref={setTrack}
      data-slot="data-grid-scrollbar"
      data-orientation={props.orientation}
      class={cn(
        SCROLLBAR_CLASS,
        SCROLLBAR_POSITION_CLASS[props.orientation],
        !visible() && "pointer-events-none opacity-0",
      )}
      style={props.style}
      onPointerDown={(event) => {
        if (event.target !== event.currentTarget) return;

        event.preventDefault();

        const rect = event.currentTarget.getBoundingClientRect();
        const pointerOffset = isVertical() ? event.clientY - rect.top : event.clientX - rect.left;

        scrollToThumbOffset(pointerOffset - thumbSize() / 2);
      }}
    >
      <div
        data-slot="data-grid-thumb"
        class={SCROLLBAR_THUMB_CLASS}
        style={
          isVertical()
            ? { height: `${thumbSize()}px`, transform: `translateY(${thumbOffset()}px)` }
            : { width: `${thumbSize()}px`, transform: `translateX(${thumbOffset()}px)` }
        }
        onPointerDown={(event) => {
          const viewport = props.viewport();
          if (!viewport) return;

          event.preventDefault();
          event.stopPropagation();
          event.currentTarget.setPointerCapture(event.pointerId);

          drag = {
            pointerId: event.pointerId,
            start: isVertical() ? event.clientY : event.clientX,
            startScroll: isVertical() ? viewport.scrollTop : viewport.scrollLeft,
          };
        }}
        onPointerMove={(event) => {
          const viewport = props.viewport();
          const trackElement = track();

          if (!viewport || !trackElement || !drag || drag.pointerId !== event.pointerId) return;

          const trackSize = isVertical() ? trackElement.clientHeight : trackElement.clientWidth;
          const clientSize = isVertical() ? viewport.clientHeight : viewport.clientWidth;
          const scrollSize = isVertical() ? viewport.scrollHeight : viewport.scrollWidth;
          const maxScroll = Math.max(0, scrollSize - clientSize);
          const maxOffset = Math.max(0, trackSize - thumbSize());

          if (maxScroll === 0 || maxOffset === 0) return;

          const delta = (isVertical() ? event.clientY : event.clientX) - drag.start;
          const next = clamp(drag.startScroll + (delta / maxOffset) * maxScroll, 0, maxScroll);

          if (isVertical()) {
            viewport.scrollTop = next;
          } else {
            viewport.scrollLeft = next;
          }
        }}
        onPointerUp={(event) => {
          if (drag?.pointerId === event.pointerId) drag = null;
        }}
        onPointerCancel={(event) => {
          if (drag?.pointerId === event.pointerId) drag = null;
        }}
        onLostPointerCapture={() => {
          drag = null;
        }}
      />
    </div>
  );
}

/**
 * Scroll wrapper for wide or sticky-header grids.
 *
 * Upstream reaches past the shadcn wrapper straight into
 * `@base-ui/react/scroll-area` because it needs the viewport ref, per-axis
 * scrollbars, `data-slot` hooks and a pinned-column inset. Zaidan's
 * `@/registry/kobalte/ui/scroll-area` exposes none of those - its viewport ref
 * is private and it hard-codes a single vertical `<ScrollBar />` - so the
 * scroll surface is implemented with vanilla Solid inside the block rather
 * than by widening the shared primitive. The rendered contract (slots, class
 * names, CSS variables, the custom sticky-header overlay) is upstream's.
 */
function DataGridScrollArea(props: DataGridScrollAreaProps) {
  const [local, others] = splitProps(props, ["children", "class", "orientation"]);
  const grid = useDataGrid();

  const [container, setContainer] = createSignal<HTMLDivElement>();
  const [viewport, setViewport] = createSignal<HTMLDivElement>();
  const [hasCustomVerticalOverflow, setHasCustomVerticalOverflow] = createSignal(false);

  let overlay: HTMLDivElement | undefined;
  let drag: { pointerId: number; startScrollTop: number; startY: number } | null = null;
  let metrics: ScrollbarMetrics = INITIAL_METRICS;
  let observedElements: ObservedElements = {
    header: null,
    horizontalScrollbar: null,
    table: null,
    tableViewport: null,
  };

  const orientation = () => local.orientation ?? "both";
  const showHorizontal = () => orientation() !== "vertical";
  const showVertical = () => orientation() !== "horizontal";
  const usesCustomVerticalScrollbar = () =>
    showVertical() && !!grid.props.tableLayout?.headerSticky;
  // Pinned columns are sticky and never scroll, so the horizontal scrollbar
  // track is inset to span only the scrollable center region between them.
  const isColumnsPinnable = () => !!grid.props.tableLayout?.columnsPinnable;
  const scrollbarInsetStart = () => (isColumnsPinnable() ? grid.table.getStartTotalSize() : 0);
  const scrollbarInsetEnd = () => (isColumnsPinnable() ? grid.table.getEndTotalSize() : 0);

  const clearDragState = () => {
    drag = null;
    document.body.style.userSelect = "";
    document.body.style.webkitUserSelect = "";
  };

  // The overlay mounts one update after the sync that detected overflow, so it
  // misses that sync's write. Seeding it from the ref callback lands the
  // geometry before the browser paints the track.
  const setOverlayRef = (node: HTMLDivElement) => {
    overlay = node;
    applyMetrics(node, metrics);
    onCleanup(() => {
      if (overlay === node) overlay = undefined;
    });
  };

  const resetMetrics = () => {
    if (!areMetricsEqual(INITIAL_METRICS, metrics)) {
      metrics = INITIAL_METRICS;
      if (overlay) applyMetrics(overlay, INITIAL_METRICS);
    }

    setHasCustomVerticalOverflow(false);
  };

  const syncCustomVerticalScrollbar = () => {
    const containerElement = container();
    const viewportElement = viewport();

    if (!containerElement || !viewportElement || !usesCustomVerticalScrollbar()) {
      resetMetrics();
      return;
    }

    const { header, horizontalScrollbar } = observedElements;
    const headerHeight = header?.getBoundingClientRect().height ?? 0;
    const viewportHeight = viewportElement.clientHeight;
    const viewportWidth = viewportElement.clientWidth;
    const scrollHeight = viewportElement.scrollHeight;
    const scrollWidth = viewportElement.scrollWidth;
    const hasHorizontalOverflow = showHorizontal() && scrollWidth > viewportWidth + 0.5;
    const horizontalScrollbarSize = hasHorizontalOverflow
      ? horizontalScrollbar?.offsetHeight || FALLBACK_SCROLLBAR_SIZE
      : 0;
    const trackHeight = Math.max(0, viewportHeight - headerHeight - horizontalScrollbarSize);
    const maxScroll = Math.max(0, scrollHeight - viewportHeight);

    let nextMetrics: ScrollbarMetrics;

    if (trackHeight === 0 || maxScroll === 0) {
      nextMetrics = {
        hasVerticalOverflow: false,
        headerHeight,
        horizontalScrollbarSize,
        thumbHeight: trackHeight,
        thumbTop: 0,
        trackHeight,
      };
    } else {
      const bodyContentHeight = Math.max(trackHeight, scrollHeight - headerHeight);
      const thumbHeight = clamp(
        trackHeight * (trackHeight / bodyContentHeight),
        MIN_THUMB_SIZE,
        trackHeight,
      );
      const maxThumbTop = Math.max(0, trackHeight - thumbHeight);
      const thumbTop = maxThumbTop > 0 ? (viewportElement.scrollTop / maxScroll) * maxThumbTop : 0;

      nextMetrics = {
        hasVerticalOverflow: true,
        headerHeight,
        horizontalScrollbarSize,
        thumbHeight,
        thumbTop,
        trackHeight,
      };
    }

    if (!areMetricsEqual(nextMetrics, metrics)) {
      metrics = nextMetrics;
      // Scoped to the overlay, never to the container. These four properties
      // inherit, and thumbTop changes on essentially every scroll frame, so
      // writing them on the element that wraps the whole grid invalidates
      // computed style for every row and cell each frame. The overlay subtree
      // is their only reader.
      if (overlay) applyMetrics(overlay, nextMetrics);
    }

    setHasCustomVerticalOverflow(nextMetrics.hasVerticalOverflow);
  };

  createEffect(() => {
    const containerElement = container();
    const viewportElement = viewport();

    if (!containerElement || !viewportElement) return;

    if (!usesCustomVerticalScrollbar()) {
      resetMetrics();
      return;
    }

    let frame = 0;

    const scheduleSync = () => {
      cancelAnimationFrame(frame);
      frame = window.requestAnimationFrame(syncCustomVerticalScrollbar);
    };

    const observer =
      typeof ResizeObserver === "undefined" ? null : new ResizeObserver(scheduleSync);
    const observed = new Set<HTMLElement>();

    const observeElement = (element: HTMLElement | null) => {
      if (element && observer && !observed.has(element)) {
        observer.observe(element);
        observed.add(element);
      }
    };

    const resolveObservedElements = () => {
      observedElements = {
        header: containerElement.querySelector(
          '[data-slot="data-grid-table"] thead',
        ) as HTMLElement | null,
        horizontalScrollbar: containerElement.querySelector(
          '[data-slot="data-grid-scrollbar"][data-orientation="horizontal"]',
        ) as HTMLElement | null,
        table: containerElement.querySelector(
          '[data-slot="data-grid-table"]',
        ) as HTMLElement | null,
        tableViewport: containerElement.querySelector(
          '[data-slot="data-grid-table-viewport"]',
        ) as HTMLElement | null,
      };

      observeElement(observedElements.header);
      observeElement(observedElements.table);
      observeElement(observedElements.tableViewport);

      return !!(observedElements.header && observedElements.table);
    };

    observeElement(viewportElement);
    const resolvedOnMount = resolveObservedElements();

    scheduleSync();
    viewportElement.addEventListener("scroll", scheduleSync, { passive: true });

    // A table that mounts after this effect (empty state swapped for data)
    // would otherwise never be observed and the custom scrollbar would
    // overlap the sticky header. One-shot: disconnects once resolved.
    let mutationObserver: MutationObserver | null = null;
    if (!resolvedOnMount && typeof MutationObserver !== "undefined") {
      mutationObserver = new MutationObserver(() => {
        if (resolveObservedElements()) {
          mutationObserver?.disconnect();
          mutationObserver = null;
          scheduleSync();
        }
      });
      mutationObserver.observe(containerElement, { childList: true, subtree: true });
    }

    onCleanup(() => {
      cancelAnimationFrame(frame);
      observer?.disconnect();
      mutationObserver?.disconnect();
      viewportElement.removeEventListener("scroll", scheduleSync);
      clearDragState();
    });
  });

  const scrollToThumbOffset = (nextThumbTop: number) => {
    const viewportElement = viewport();
    const { thumbHeight, trackHeight } = metrics;

    if (!viewportElement) return;

    const maxScroll = Math.max(0, viewportElement.scrollHeight - viewportElement.clientHeight);
    const maxThumbTop = Math.max(0, trackHeight - thumbHeight);

    if (maxScroll === 0 || maxThumbTop === 0) {
      viewportElement.scrollTop = 0;
      return;
    }

    const ratio = clamp(nextThumbTop, 0, maxThumbTop) / maxThumbTop;
    viewportElement.scrollTop = ratio * maxScroll;
  };

  const handleThumbPointerDown = (event: PointerEvent & { currentTarget: HTMLDivElement }) => {
    const viewportElement = viewport();

    if (!viewportElement) return;

    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.setPointerCapture(event.pointerId);

    drag = {
      pointerId: event.pointerId,
      startScrollTop: viewportElement.scrollTop,
      startY: event.clientY,
    };

    document.body.style.userSelect = "none";
    document.body.style.webkitUserSelect = "none";
  };

  const handleThumbPointerMove = (event: PointerEvent) => {
    const viewportElement = viewport();
    const dragState = drag;
    const { thumbHeight, trackHeight } = metrics;

    if (!viewportElement || !dragState || dragState.pointerId !== event.pointerId) {
      return;
    }

    const maxThumbTop = Math.max(0, trackHeight - thumbHeight);
    const maxScroll = Math.max(0, viewportElement.scrollHeight - viewportElement.clientHeight);

    if (maxThumbTop === 0 || maxScroll === 0) return;

    const deltaY = event.clientY - dragState.startY;
    const nextScrollTop = dragState.startScrollTop + (deltaY / maxThumbTop) * maxScroll;

    viewportElement.scrollTop = clamp(nextScrollTop, 0, maxScroll);
  };

  const handleThumbPointerUp = (event: PointerEvent) => {
    if (drag?.pointerId !== event.pointerId) return;
    clearDragState();
  };

  const handleTrackPointerDown = (event: PointerEvent & { currentTarget: HTMLDivElement }) => {
    const { thumbHeight } = metrics;

    if (event.target !== event.currentTarget) return;

    event.preventDefault();
    event.stopPropagation();

    const rect = event.currentTarget.getBoundingClientRect();
    const offsetY = event.clientY - rect.top - thumbHeight / 2;

    scrollToThumbOffset(offsetY);
  };

  return (
    <div ref={setContainer} class="relative">
      <div
        data-slot="data-grid-scroll-area"
        // Styling hook: present while the sticky-header scroll mode detects
        // vertical overflow, so consumers can style scrollable vs short
        // grids with a plain ancestor attribute selector.
        data-overflow-vertical={hasCustomVerticalOverflow() ? "true" : undefined}
        class={cn("relative", local.class)}
        {...others}
      >
        <div
          ref={setViewport}
          data-slot="scroll-area-viewport"
          class={cn("size-full", VIEWPORT_SCROLL_CLASS)}
        >
          <div data-slot="scroll-area-content">{local.children}</div>
        </div>

        <Show when={showHorizontal()}>
          <DataGridScrollAreaScrollbar
            orientation="horizontal"
            viewport={viewport}
            style={
              scrollbarInsetStart() > 0 || scrollbarInsetEnd() > 0
                ? {
                    "margin-inline-start": scrollbarInsetStart()
                      ? `${scrollbarInsetStart()}px`
                      : undefined,
                    "margin-inline-end": scrollbarInsetEnd()
                      ? `${scrollbarInsetEnd()}px`
                      : undefined,
                  }
                : undefined
            }
          />
        </Show>

        <Show when={showVertical() && !usesCustomVerticalScrollbar()}>
          <DataGridScrollAreaScrollbar orientation="vertical" viewport={viewport} />
        </Show>
      </div>

      <Show when={usesCustomVerticalScrollbar() && hasCustomVerticalOverflow()}>
        <div
          ref={setOverlayRef}
          aria-hidden="true"
          class="pointer-events-none absolute inset-e-0 top-(--data-grid-scrollbar-header-height) z-20 h-(--data-grid-scrollbar-track-height)"
        >
          <div
            class="pointer-events-auto relative h-full w-2 touch-none p-px"
            onPointerDown={handleTrackPointerDown}
          >
            <div
              class={cn(
                "bg-border absolute end-px w-2",
                "top-(--data-grid-scrollbar-thumb-top) h-(--data-grid-scrollbar-thumb-height)",
                "rounded-full",
              )}
              onLostPointerCapture={clearDragState}
              onPointerCancel={handleThumbPointerUp}
              onPointerDown={handleThumbPointerDown}
              onPointerMove={handleThumbPointerMove}
              onPointerUp={handleThumbPointerUp}
            />
          </div>
        </div>
      </Show>
    </div>
  );
}

export type { DataGridScrollAreaOrientation, DataGridScrollAreaProps };
export { DataGridScrollArea };

import type { Cell, Column, Header, Row } from "@tanstack/solid-table";
import { flexRender } from "@tanstack/solid-table";
import type { JSX } from "solid-js";
import {
  children,
  createEffect,
  createMemo,
  createSignal,
  For,
  Match,
  onCleanup,
  Show,
  Switch,
  untrack,
} from "solid-js";

import { cn } from "@/lib/utils";
import { Checkbox } from "@/registry/kobalte/ui/checkbox";
import { Spinner } from "@/registry/kobalte/ui/spinner";
import type { DataGridFeatures, DataGridTableInstance } from "./data-grid";
import { useDataGrid } from "./data-grid";

// Static spacing lookups; called once per cell, so they stay plain string
// picks instead of runtime variant machinery.
const headerCellSpacingVariants = ({ size }: { size?: "dense" | "default" }) =>
  size === "dense" ? "px-2 h-8" : "px-3";

const bodyCellSpacingVariants = ({ size }: { size?: "dense" | "default" }) =>
  size === "dense" ? "px-2 py-1.5" : "px-3 py-2";

const footerCellSpacingVariants = ({ size }: { size?: "dense" | "default" }) =>
  size === "dense" ? "px-2 py-1.5" : "px-3 py-2";

/**
 * Solid applies `style` objects through `setProperty`, so every declaration
 * below is written in hyphenated CSS form with explicit units.
 */
function getPinningStyles<TData extends object>(
  column: Column<DataGridFeatures, TData, unknown>,
): JSX.CSSProperties {
  const isPinned = column.getIsPinned();

  return {
    // Logical offsets: TanStack's "left"/"right" buckets are start/end
    // semantics, so pinned columns stick to the correct edge in RTL too
    // (identical to left/right in LTR).
    "inset-inline-start": isPinned === "start" ? `${column.getStart("start")}px` : undefined,
    "inset-inline-end": isPinned === "end" ? `${column.getAfter("end")}px` : undefined,
    position: isPinned ? "sticky" : undefined,
    transform: isPinned ? "translateZ(0)" : undefined,
    contain: isPinned ? "paint" : undefined,
    width: `${column.getSize()}px`,
    "z-index": isPinned ? 30 : undefined,
    "background-clip": isPinned ? "padding-box" : undefined,
  };
}

// Shared indent contract for tree rows: DataGridTableRowExpand consumes it,
// and fully custom cells can reuse it for depth alignment without the
// built-in toggle.
function getDataGridTreeIndentStyle<TData extends object>(
  row: Row<DataGridFeatures, TData>,
  indent = 20,
): JSX.CSSProperties {
  return {
    "--data-grid-tree-padding": `${row.depth * indent}px`,
  };
}

/**
 * Solid refs are plain callbacks, so the grid's optional ref props are too.
 * Unlike React they are never called with `null`; teardown belongs in
 * `onCleanup`.
 */
type DataGridRefCallback<T> = (element: T) => void;

function assignRef<T>(ref: DataGridRefCallback<T> | undefined, value: T) {
  ref?.(value);
}

/**
 * Nearest scroll-area viewport that belongs to THIS grid. A viewport outside
 * the grid's own container (e.g. a page-level ScrollArea) would make the
 * width measurement - and the virtualizer - bind the wrong box.
 */
function getDataGridScrollAreaViewport(node: HTMLElement): HTMLElement | null {
  const scrollViewport = node.closest('[data-slot="scroll-area-viewport"]') as HTMLElement | null;

  if (!scrollViewport) return null;

  const gridContainer = node.closest('[data-slot="data-grid"]');
  if (gridContainer && !gridContainer.contains(scrollViewport)) return null;

  return scrollViewport;
}

type DataGridResizeStartEvent =
  | (MouseEvent & { currentTarget: HTMLDivElement })
  | (TouchEvent & { currentTarget: HTMLDivElement });

type DataGridResizeDocumentEvent = globalThis.MouseEvent | globalThis.TouchEvent;

function isDataGridTouchEvent(
  event: DataGridResizeStartEvent | DataGridResizeDocumentEvent,
): event is (TouchEvent & { currentTarget: HTMLDivElement }) | globalThis.TouchEvent {
  return "touches" in event;
}

type DataGridTouchListLike = {
  length: number;
  item: (index: number) => { identifier: number; clientX: number } | null;
};

function findTouchClientX(list: DataGridTouchListLike, identifier: number) {
  for (let i = 0; i < list.length; i++) {
    const touch = list.item(i);
    if (touch && touch.identifier === identifier) return touch.clientX;
  }

  return undefined;
}

function getDataGridResizeEventClientX(
  event: DataGridResizeStartEvent | DataGridResizeDocumentEvent,
  touchIdentifier?: number,
) {
  if (isDataGridTouchEvent(event)) {
    if (typeof touchIdentifier === "number") {
      return (
        findTouchClientX(event.touches, touchIdentifier) ??
        findTouchClientX(event.changedTouches, touchIdentifier)
      );
    }

    return event.touches[0]?.clientX ?? event.changedTouches[0]?.clientX;
  }

  return event.clientX;
}

function startDataGridColumnResizeOnEnd<TData extends object>(
  event: DataGridResizeStartEvent,
  header: Header<DataGridFeatures, TData, unknown>,
  table: DataGridTableInstance<TData>,
): (() => void) | undefined {
  const column = table.getColumn(header.column.id);

  if (!column?.getCanResize()) return;
  const isTouchSession = isDataGridTouchEvent(event);
  if (isTouchSession && event.touches.length > 1) return;

  const ownerDocument = event.currentTarget.ownerDocument;
  const ownerWindow = ownerDocument.defaultView;
  const previousBodyCursor = ownerDocument.body.style.cursor;
  const previousDocumentCursor = ownerDocument.documentElement.style.cursor;
  const startSize = header.getSize();
  // Track the initiating finger so a second touch cannot move or commit the
  // resize with the wrong clientX.
  const touchIdentifier = isTouchSession ? event.touches[0]?.identifier : undefined;
  const dragStartClientX = getDataGridResizeEventClientX(event, touchIdentifier);
  const headerCell = event.currentTarget.closest("th");
  const headerRect = headerCell?.getBoundingClientRect();
  const startOffset =
    headerRect &&
    Number.isFinite(
      table.options.columnResizeDirection === "rtl" ? headerRect.left : headerRect.right,
    )
      ? table.options.columnResizeDirection === "rtl"
        ? headerRect.left
        : headerRect.right
      : dragStartClientX;

  if (typeof dragStartClientX !== "number" || typeof startOffset !== "number") {
    return;
  }

  ownerDocument.body.style.cursor = "col-resize";
  ownerDocument.documentElement.style.cursor = "col-resize";

  const columnSizingStart = header
    .getLeafHeaders()
    .map((leafHeader) => [leafHeader.column.id, leafHeader.column.getSize()] as [string, number]);
  const directionMultiplier = table.options.columnResizeDirection === "rtl" ? -1 : 1;

  // Clamp the drag to the leaf columns' min/max sizes so the preview
  // indicator matches what the commit will produce (no overshoot followed by
  // a snap-back on release). columnDef always carries resolved defaults.
  let minDeltaPercentage = -0.999999;
  let maxDeltaPercentage = Number.POSITIVE_INFINITY;
  for (const [columnId, headerSize] of columnSizingStart) {
    if (headerSize <= 0) continue;

    const leafColumn = table.getColumn(columnId);
    const minSize = leafColumn?.columnDef.minSize;
    const maxSize = leafColumn?.columnDef.maxSize;

    if (typeof minSize === "number") {
      minDeltaPercentage = Math.max(minDeltaPercentage, minSize / headerSize - 1);
    }
    if (typeof maxSize === "number" && Number.isFinite(maxSize)) {
      maxDeltaPercentage = Math.min(maxDeltaPercentage, maxSize / headerSize - 1);
    }
  }

  let lastClientX = dragStartClientX;
  let ended = false;
  const stopListeners: Array<() => void> = [];

  const updateOffset = (clientXPos?: number, commit = false) => {
    if (typeof clientXPos !== "number") return;

    lastClientX = clientXPos;

    const nextColumnSizing: Record<string, number> = {};
    const deltaPercentage = Math.min(
      Math.max(
        ((clientXPos - dragStartClientX) * directionMultiplier) / startSize,
        minDeltaPercentage,
      ),
      maxDeltaPercentage,
    );
    const deltaOffset = deltaPercentage * startSize;

    for (const [columnId, headerSize] of columnSizingStart) {
      nextColumnSizing[columnId] =
        Math.round(Math.max(headerSize + headerSize * deltaPercentage, 0) * 100) / 100;
    }

    table.setColumnResizing((old) => ({
      ...old,
      startOffset,
      startSize,
      deltaOffset,
      deltaPercentage,
      columnSizingStart,
      isResizingColumn: column.id,
    }));

    if (commit) {
      table.setColumnSizing((old) => ({
        ...old,
        ...nextColumnSizing,
      }));
    }
  };

  // Single teardown path: commits at the given position, removes every
  // document/window listener, and restores cursors. Safe to call more than
  // once (blur + mouseup + unmount can race).
  const endResize = (clientXPos?: number) => {
    if (ended) return;
    ended = true;

    for (const stop of stopListeners) stop();
    updateOffset(clientXPos, true);
    table.setColumnResizing((old) => ({
      ...old,
      isResizingColumn: false,
      startOffset: null,
      startSize: null,
      deltaOffset: null,
      deltaPercentage: null,
      columnSizingStart: [],
    }));
    ownerDocument.body.style.cursor = previousBodyCursor;
    ownerDocument.documentElement.style.cursor = previousDocumentCursor;
  };

  const mouseMoveHandler = (moveEvent: globalThis.MouseEvent) => {
    updateOffset(moveEvent.clientX);
  };
  const mouseUpHandler = (upEvent: globalThis.MouseEvent) => {
    endResize(upEvent.clientX);
  };
  const touchMoveHandler = (moveEvent: globalThis.TouchEvent) => {
    if (moveEvent.cancelable) {
      moveEvent.preventDefault();
      moveEvent.stopPropagation();
    }

    updateOffset(getDataGridResizeEventClientX(moveEvent, touchIdentifier));
  };
  const touchEndHandler = (endEvent: globalThis.TouchEvent) => {
    // Ignore other fingers lifting; only the initiating touch ends the drag.
    const clientXPos =
      typeof touchIdentifier === "number"
        ? findTouchClientX(endEvent.changedTouches, touchIdentifier)
        : getDataGridResizeEventClientX(endEvent);

    if (typeof clientXPos !== "number") return;

    if (endEvent.cancelable) {
      endEvent.preventDefault();
      endEvent.stopPropagation();
    }

    endResize(clientXPos);
  };
  // System-interrupted gestures and window focus loss would otherwise leave
  // the session (and its document listeners) live with no pointer held.
  const touchCancelHandler = () => {
    endResize(lastClientX);
  };
  const windowBlurHandler = () => {
    endResize(lastClientX);
  };

  const passiveIfSupported = { passive: false } as const;

  if (isTouchSession) {
    ownerDocument.addEventListener("touchmove", touchMoveHandler, passiveIfSupported);
    ownerDocument.addEventListener("touchend", touchEndHandler, passiveIfSupported);
    ownerDocument.addEventListener("touchcancel", touchCancelHandler);
    stopListeners.push(() => {
      ownerDocument.removeEventListener("touchmove", touchMoveHandler);
      ownerDocument.removeEventListener("touchend", touchEndHandler);
      ownerDocument.removeEventListener("touchcancel", touchCancelHandler);
    });
  } else {
    ownerDocument.addEventListener("mousemove", mouseMoveHandler, passiveIfSupported);
    ownerDocument.addEventListener("mouseup", mouseUpHandler, passiveIfSupported);
    stopListeners.push(() => {
      ownerDocument.removeEventListener("mousemove", mouseMoveHandler);
      ownerDocument.removeEventListener("mouseup", mouseUpHandler);
    });
  }

  if (ownerWindow) {
    ownerWindow.addEventListener("blur", windowBlurHandler);
    stopListeners.push(() => ownerWindow.removeEventListener("blur", windowBlurHandler));
  }

  table.setColumnResizing((old) => ({
    ...old,
    startOffset,
    startSize,
    deltaOffset: 0,
    deltaPercentage: 0,
    columnSizingStart,
    isResizingColumn: column.id,
  }));

  return () => endResize(lastClientX);
}

type DataGridTablePinnedBoundary = "top" | "bottom";

function getDataGridTableRowSections<TData extends object>(
  table: DataGridTableInstance<TData>,
  rowsPinnable?: boolean,
) {
  if (!rowsPinnable) {
    return {
      topRows: [] as Row<DataGridFeatures, TData>[],
      centerRows: table.getRowModel().rows as Row<DataGridFeatures, TData>[],
      bottomRows: [] as Row<DataGridFeatures, TData>[],
    };
  }

  return {
    topRows: table.getTopRows() as Row<DataGridFeatures, TData>[],
    centerRows: table.getCenterRows() as Row<DataGridFeatures, TData>[],
    bottomRows: table.getBottomRows() as Row<DataGridFeatures, TData>[],
  };
}

function getDataGridTableResolvedRows<TData extends object>(
  table: DataGridTableInstance<TData>,
  rowsPinnable?: boolean,
) {
  const { topRows, centerRows, bottomRows } = getDataGridTableRowSections(table, rowsPinnable);
  const resolvedRows: Array<{
    row: Row<DataGridFeatures, TData>;
    pinnedBoundary?: DataGridTablePinnedBoundary;
  }> = [];

  topRows.forEach((row, index) => {
    resolvedRows.push({
      row,
      pinnedBoundary:
        index === topRows.length - 1 && (centerRows.length > 0 || bottomRows.length > 0)
          ? "top"
          : undefined,
    });
  });

  for (const row of centerRows) {
    resolvedRows.push({ row });
  }

  bottomRows.forEach((row, index) => {
    resolvedRows.push({
      row,
      pinnedBoundary:
        index === 0 && (centerRows.length > 0 || topRows.length > 0) ? "bottom" : undefined,
    });
  });

  return resolvedRows;
}

function getDataGridTableOrderedVisibleColumns<TData extends object>(
  table: DataGridTableInstance<TData>,
) {
  return [
    ...table.getStartVisibleLeafColumns(),
    ...table.getCenterVisibleLeafColumns(),
    ...table.getEndVisibleLeafColumns(),
  ] as Column<DataGridFeatures, TData, unknown>[];
}

function getDataGridTableOrderedVisibleCells<TData extends object>(
  row: Row<DataGridFeatures, TData>,
) {
  return [
    ...row.getStartVisibleCells(),
    ...row.getCenterVisibleCells(),
    ...row.getEndVisibleCells(),
  ] as Cell<DataGridFeatures, TData, unknown>[];
}

function getDataGridTableMergedHeaderGroups<TData extends object>(
  table: DataGridTableInstance<TData>,
) {
  const leftHeaderGroups = table.getStartHeaderGroups();
  const centerHeaderGroups = table.getCenterHeaderGroups();
  const rightHeaderGroups = table.getEndHeaderGroups();
  const headerGroupCount = Math.max(
    leftHeaderGroups.length,
    centerHeaderGroups.length,
    rightHeaderGroups.length,
  );

  return Array.from({ length: headerGroupCount }, (_, index) => {
    const leftGroup = leftHeaderGroups[index];
    const centerGroup = centerHeaderGroups[index];
    const rightGroup = rightHeaderGroups[index];

    return {
      id:
        [leftGroup?.id, centerGroup?.id, rightGroup?.id].filter(Boolean).join(":") ||
        `header-group-${index}`,
      headers: [
        ...(leftGroup?.headers ?? []),
        ...(centerGroup?.headers ?? []),
        ...(rightGroup?.headers ?? []),
      ] as Header<DataGridFeatures, TData, unknown>[],
    };
  });
}

function hasDataGridTableRightPinnedColumns<TData extends object>(
  table: DataGridTableInstance<TData>,
) {
  return (table.store.state.columnPinning.end?.length ?? 0) > 0;
}

function DataGridTableFillCol() {
